import torch

class RolloutBuffer:
    def __init__(self, steps, num_env, num_obs, num_action, device="cpu"):
        # storing rollout data generated by Policy 0
        self.num_steps = steps
        self.num_env = num_env
        self.num_obs = num_obs
        self.num_action = num_action # output dim
        self.device = device

        self.obs = torch.zeros(self.num_steps, self.num_env, 
                               self.num_obs, device=self.device)
        self.action = torch.zeros(self.num_steps, self.num_env, 
                                  self.num_action, device=self.device)
        self.value = torch.zeros(self.num_steps, self.num_env,
                                 device=self.device)
        self.reward = torch.zeros(self.num_steps, self.num_env,
                                    device=self.device)
        self.log_prob = torch.zeros(self.num_steps, self.num_env,
                                    device=self.device)

        # episode boundary: terminated OR truncated
        self.dones = torch.zeros(self.num_steps, self.num_env,
                                 dtype=torch.bool, device=self.device)
        # self.terminated = torch.zeros(self.num_step, self.num_env,
        #                             dtype=torch.bool, device=self.device)
        # self.truncated = torch.zeros(self.num_step, self.num_env,
        #                             dtype=torch.bool, device=self.device)

        # computed after rollout collection for GAE
        self.advantage = torch.zeros(self.num_steps, self.num_env,
                                    device=self.device)
        self.returns = torch.zeros(self.num_steps, self.num_env,
                                    device=self.device)
        
        # Utilities
        self.step = 0

    # one rollout --> n timestep
    def add(self, obs, action, value, reward, log_prob, done): 
        assert self.step < self.num_steps, "Rollout buffer is full"
        # store Policy 0 obs (timestep, env, obs)
        self.obs[self.step] = obs # replace the entire 2D block 
        # store Policy 0 action (timestep, env, action)
        self.action[self.step] = action # for comparing ratio
        # store Policy 0 V(s) from critic (timestep, env)
        self.value[self.step] = value # for computing advantage
        # store Policy 0 env reward (timestep, env)
        self.reward[self.step] = reward # for computing advantage
        # store Policy 0 log π_old(a_t | s_t) (timestep, env)
        self.log_prob[self.step] = log_prob
        # store whether the episode ended at this transition
        self.dones[self.step] = done
        # increment update
        self.step += 1

    def compute_gae(self, last_value, gamma=0.99, gae_lambda=0.95):
        assert self.step == self.num_steps, "Rollout buffer is not full"
        # one GAE value per parallel env
        gae = torch.zeros(self.num_env, device=self.device)
        # iterate backwards 
        for t in reversed(range(self.num_steps)):
            if t == self.num_steps-1:
                next_value = last_value
            else:
                next_value = self.value[t + 1]

            mask = (~self.dones[t]).float()
            
            # compute delta TD error (2048,)
            delta = self.reward[t] + mask * \
                (gamma * next_value) - self.value[t]

            # compute advantage (2048,)
            gae = delta + mask *\
                  (gae_lambda * gamma * gae)
            self.advantage[t] = gae
            
        # compute the returns for critic loss
        self.returns = self.advantage + self.value

    def flatten(self):
        # before input into PPO (steps, env, ...) --> (steps*env, ...)
        batch_size = self.num_steps * self.num_env

        # reshaping
        obs = self.obs.reshape(batch_size, self.num_obs)
        action = self.action.reshape(batch_size, self.num_action)
        value = self.value.reshape(batch_size)
        log_prob = self.log_prob.reshape(batch_size)
        advantage = self.advantage.reshape(batch_size)
        returns = self.returns.reshape(batch_size)

        return obs, action, value, log_prob, advantage, returns

    def minibatches(self, minibatch_size):
        # flattening
        obs, action, value, log_prob, advantage, returns = self.flatten()

        # normalizing advantage --> stable training
        advantage = (advantage - advantage.mean()) / (advantage.std() + 1e-8)

        # generating minibatches
        batch_size = obs.shape[0] # steps * env
        # randomnize the input vector
        indices = torch.randperm(batch_size, device=self.device)
        for start in range(0, batch_size, minibatch_size):
            end = start + minibatch_size
            mb_indices = indices[start:end] # slicing operation

            yield (obs[mb_indices], action[mb_indices],
                   log_prob[mb_indices], advantage[mb_indices],
                   returns[mb_indices], value[mb_indices])


    def reset(self):
        self.step = 0